function finishCallTurn(isKan) {
  state.lastDiscard = null;
  state.pendingCalls = null;
  state.current = SEAT_EAST;
  state.phase = 'human_turn';
  state.drawnIndex = -1;
  if (isKan) {
    drawRinshan(SEAT_EAST);
    revealExtraDora();
    setMessage('カンしました。嶺上ツモ後、1枚捨ててください。');
  } else {
    setMessage('鳴きました。手牌から1枚捨ててください。');
  }
  renderAll();
}

function doAnkan(tile) {
  const p = players[SEAT_EAST];
  if (p.hand.filter(t => t === tile).length < 4) return;
  removeTilesFromHand(SEAT_EAST, [tile, tile, tile, tile]);
  p.melds.push({ type: 'ankan', tiles: [tile, tile, tile, tile], open: false, called: tile });
  drawRinshan(SEAT_EAST);
  revealExtraDora();
  if (p.riichi) p.ippatsu = false;
  setMessage('暗槓しました。嶺上ツモ後、捨て牌を選んでください。');
  renderAll();
}

function doKakan(info) {
  const p = players[SEAT_EAST];
  const m = p.melds[info.meldIndex];
  if (!m || m.type !== 'pon') return;
  const i = p.hand.indexOf(info.tile);
  if (i < 0) return;
  p.hand.splice(i, 1);
  m.type = 'kakan';
  m.tiles = [info.tile, info.tile, info.tile, info.tile];
  drawRinshan(SEAT_EAST);
  revealExtraDora();
  if (p.riichi) p.ippatsu = false;
  setMessage('加槓しました。嶺上ツモ後、捨て牌を選んでください。');
  renderAll();
}

