els.btnKan.addEventListener('click', () => {
  if (state.pendingCalls && state.pendingCalls.kanDaiminkan) {
    doDaiminkan();
    return;
  }
  if (state.phase === 'human_turn') {
    const kk = findKakanOptions(players[SEAT_EAST]);
    if (kk) { doKakan(kk); return; }
    const an = findAnkanOptions(players[SEAT_EAST].hand);
    if (an.length) doAnkan(an[0]);
  }
});
els.btnPassCall.addEventListener('click', passCallsAndContinue);

